struct Money { long cents; char currency[4]; };

void to_json(nlohmann::json& j, const Money& m) {
    j = nlohmann::json{{"cents", m.cents}, {"currency", m.currency}};
}
void from_json(const nlohmann::json& j, Money& m) {
    j.at("cents").get_to(m.cents);
    std::strncpy(m.currency, j.at("currency").get<std::string>().c_str(), 4);
}
